SELECT objRec.* FROM ( SELECT tmp3.PROD_ID, tmp3.VDATE, tmp3.RAISE_QTY, tmp3.TOTAL_AMT FROM ( SELECT @rownum :=@rownum +1 rownum, tmp2.PROD_ID, tmp2.VDATE, B.RAISE_QTY, B.TOTAL_AMT, IF (@PROD_ID = tmp2.PROD_ID, @rank :=@rank + 1, @rank :=1 ) AS raiseStatusNo, @PROD_ID := tmp2.PROD_ID FROM (SELECT * FROM ( SELECT A.PROD_ID, A.VDATE FROM CHB_PRD_BASEINFO A LEFT JOIN ( SELECT PROD_ID, MAX(MDATE) FROM CHB_PRD_DEAL_SUB WHERE STATUS IN ('01','02') AND STR_TO_DATE(DATE_FORMAT(MDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') GROUP BY PROD_ID ) tmp1 ON A.PROD_ID = tmp1.PROD_ID WHERE tmp1.PROD_ID is null AND A.FPROD_ID is null AND A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
) aa ORDER BY PROD_ID, STATUS, UPDATE_TIME ) tmp2, (SELECT @rownum :=0, @PROD_REGIST_CODE := NULL, @rank := 0) tmp INNER JOIN CHB_PRD_RAISETOT_SUB B ON (tmp2.PROD_ID = B.PROD_ID AND STATUS IN ('01','02')) ) tmp3 WHERE raiseStatusNo = 1 ) objRec
